static void sendNanoState();

static uint8_t crc8(const char *s,size_t n){uint8_t c=0;while(n--){c^=(uint8_t)*s++;for(uint8_t b=0;b<8;b++)c=(c&0x80)?(uint8_t)((c<<1)^0x07):(uint8_t)(c<<1);}return c;}
static void sendFrame(const char *payload){nanoLink.print(payload);nanoLink.print('*');char h[3];snprintf(h,sizeof(h),"%02X",crc8(payload,strlen(payload)));nanoLink.println(h);Serial.printf("[ESP TX] %s*%s\n",payload,h);}
static bool validFrame(char *s){char *p=strrchr(s,'*');if(!p||strlen(p)!=3)return false;if(crc8(s,p-s)!=(uint8_t)strtoul(p+1,nullptr,16))return false;*p='\0';return true;}
static bool authorized(){if(!uiAuth)return true;if(!server.authenticate("admin",uiPassword.c_str())){server.requestAuthentication();return false;}return true;}
static bool otaAuthorized(){if(!updatePasswordSet||!server.authenticate("admin",uiPassword.c_str())){server.requestAuthentication();return false;}return true;}
static uint32_t uptimeS(){return (millis()-bootMs)/1000;}
static void setWifiLed(bool on){digitalWrite(8,on?LOW:HIGH);} // Super Mini blue LED is active-low on GPIO8.

static uint16_t addOpenEvent(uint32_t sec,uint32_t duration){uint16_t slot=eventHead;openings[slot]={sec,duration};eventHead=(eventHead+1)%100;if(eventCount<100)eventCount++;openingEvents++;return slot;}
static void addHeaterEvent(uint32_t sec,bool on,bool baseline=false){heaterEvents[heaterHead]={sec,(uint8_t)(on?1:0),(uint8_t)(baseline?1:0)};heaterHead=(heaterHead+1)%200;if(heaterCount<200)heaterCount++;}
static void addSample(){Sample &s=history[histHead];s.sec=uptimeS();s.temp10=isnan(tempC)?-32768:(int16_t)(tempC*10);s.set10=(int16_t)(targetC*10);s.heater=heaterOn;s.lid=lidClosed?0:1;histHead=(histHead+1)%1080;if(histCount<1080)histCount++;}
static float avgBake(){return bakeDurationN?(float)bakeDurationSum/bakeDurationN:NAN;}
static float avgOpen(){return lidOpenDurationN?(float)lidOpenDurationSum/lidOpenDurationN:NAN;}
static float ratePerHour(){if(completedTimesN<2)return NAN;uint8_t intervals=completedTimesN-1;uint64_t sum=0;for(uint8_t i=0;i<intervals;i++){uint8_t a=(completedTimesHead+11-completedTimesN+i)%11;uint8_t b=(a+1)%11;sum+=(uint32_t)(completedTimes[b]-completedTimes[a]);}float mean=(float)sum/intervals;return mean>0?3600.0f/mean:NAN;}
static void completeBake(){uint32_t now=uptimeS();uint32_t total=(millis()-bakeStartedMs)/1000;completed++;bakeDurationSum+=total;bakeDurationN++;completedTimes[completedTimesHead]=now;completedTimesHead=(completedTimesHead+1)%11;if(completedTimesN<11)completedTimesN++;Serial.printf("[ESP] Bake completed: count=%lu, duration=%lu s\n",(unsigned long)completed,(unsigned long)total);bakeState=0;bakeElapsedS=0;overtimeS=0;}

static void parseNano(char *line){if(!validFrame(line)){Serial.printf("[ESP CRC ERR] %s\n",line);return;}char *save=nullptr;char *kind=strtok_r(line,",",&save);char *seqStr=strtok_r(nullptr,",",&save);if(!kind||!seqStr)return;
  if(!strcmp(kind,"ACK")){lastAckSeq=strtoul(seqStr,nullptr,10);char *result=strtok_r(nullptr,",",&save);lastAckOk=result&&!strcmp(result,"OK");if(!lastAckOk)Serial.printf("[ESP] Nano rejected command sequence %lu\n",(unsigned long)lastAckSeq);else lastNanoFrameMs=millis();return;}
  if(strcmp(kind,"IO")&&strcmp(kind,"EV"))return;uint32_t incomingSeq=strtoul(seqStr,nullptr,10);if(haveNanoSeq&&(int32_t)(incomingSeq-lastNanoSeq)<=0){if((int32_t)(lastNanoSeq-incomingSeq)>50){lastNanoSeq=incomingSeq;}else{return;}}lastNanoSeq=incomingSeq;haveNanoSeq=true;lastNanoFrameMs=millis();
  if(!strcmp(kind,"IO")){char *t=strtok_r(nullptr,",",&save);char *closed=strtok_r(nullptr,",",&save);char *heat=strtok_r(nullptr,",",&save);char *fault=strtok_r(nullptr,",",&save);strtok_r(nullptr,",",&save);char *openS=strtok_r(nullptr,",",&save);char *nanoLinkFlag=strtok_r(nullptr,",",&save);char *legacyT=strtok_r(nullptr,",",&save);char *legacyD=strtok_r(nullptr,",",&save);
    bool wasClosed=lidClosed,wasHeater=heaterOn;if(t){float v=atof(t);tempC=(v<0||v>250)?NAN:v;}if(closed)lidClosed=atoi(closed)!=0;if(heat)heaterOn=atoi(heat)!=0;if(fault)sensorFault=atoi(fault)!=0;if(!haveHeaterState){addHeaterEvent(uptimeS(),heaterOn,true);haveHeaterState=true;}else if(wasHeater!=heaterOn)addHeaterEvent(uptimeS(),heaterOn);
    if(wasClosed&&!lidClosed){lidOpenStartMs=millis();activeOpenSlot=addOpenEvent(uptimeS(),0);if(bakeState==2)completeBake();else {bakeState=0;bakeElapsedS=0;overtimeS=0;}}
    if(!wasClosed&&lidClosed&&lidOpenStartMs){uint32_t d=(millis()-lidOpenStartMs)/1000;lidOpenDurationSum+=d;lidOpenDurationN++;if(activeOpenSlot>=0)openings[activeOpenSlot].openSec=d;lidOpenStartMs=0;activeOpenSlot=-1;}
    if(legacyT&&legacyD){int lt=atoi(legacyT),ld=atoi(legacyD);if(lt>=100&&lt<=160&&ld>=10&&ld<=90){if(importTargetPending){targetC=lt;prefs.putInt("target",lt);importTargetPending=false;}if(importDurationPending){durationS=ld;prefs.putInt("duration",ld);importDurationPending=false;}}}
    nanoHeartbeatReady=nanoLinkFlag&&atoi(nanoLinkFlag)!=0;
    if(openS&&atoi(openS)>0){} // duration is measured locally between stable transitions
  } else if(!strcmp(kind,"EV")){char *ev=strtok_r(nullptr,",",&save);if(ev&&!strcmp(ev,"START")){if(nanoUp&&!sensorFault&&lidClosed){runEnabled=true;Serial.println(F("[ESP] Local START accepted"));}else Serial.println(F("[ESP] Local START rejected by safety checks"));}else if(ev&&!strcmp(ev,"STOP")){runEnabled=false;bakeState=0;Serial.println(F("[ESP] Local STOP received"));}else if(ev&&!strcmp(ev,"MODE")){encoderTimeMode=!encoderTimeMode;Serial.printf("[ESP] Encoder edits %s\n",encoderTimeMode?"duration":"temperature");}else if(ev&&!strcmp(ev,"ENC")){char *deltaText=strtok_r(nullptr,",",&save);int delta=deltaText?atoi(deltaText):0;if(!importTargetPending&&!importDurationPending&&delta){if(encoderTimeMode)durationS=constrain(durationS+delta,10,90);else targetC=constrain(targetC+delta,100,160);settingsDirty=true;settingsChangedMs=millis();Serial.printf("[ESP] Encoder changed setting: target=%d C, duration=%d s\n",targetC,durationS);}}}
}
static void pollNano(){while(nanoLink.available()){char c=(char)nanoLink.read();if(c=='\n'||c=='\r'){if(rxLen){rxLine[rxLen]=0;Serial.printf("[ESP RX] %s\n",rxLine);parseNano(rxLine);rxLen=0;}}else if(rxLen<sizeof(rxLine)-1)rxLine[rxLen++]=c;else rxLen=0;}}

static void updateBake(){uint32_t now=millis();if(!nanoUp||sensorFault||!runEnabled){bakeState=0;return;}if(!lidClosed){if(bakeState==1){bakeState=0;}return;}if(bakeState==0){if(isnan(tempC)||tempC<targetC)return;bakeState=1;bakeStartedMs=now;bakeElapsedS=0;overtimeS=0;}if(bakeState==1){bakeElapsedS=(now-bakeStartedMs)/1000;if(bakeElapsedS>=durationS)bakeState=2;}if(bakeState==2)overtimeS=(now-bakeStartedMs)/1000-durationS;}

static void sendNanoHello(){char out[32];snprintf(out,sizeof(out),"CMD,%lu,HELLO",(unsigned long)++seq);sendFrame(out);lastHelloMs=millis();nanoSessionStarted=true;haveNanoSeq=false;}
static void sendNanoState(){uint32_t rem=bakeState==1&&bakeElapsedS<durationS?durationS-bakeElapsedS:0;char out[kMaxLineLength];snprintf(out,sizeof(out),"CMD,%lu,STATE,%d,%d,%u,%lu,%lu,%lu,%u",(unsigned long)++seq,targetC,durationS,runEnabled?1:0,(unsigned long)completed,(unsigned long)rem,(unsigned long)overtimeS,(unsigned)bakeState);sendFrame(out);}

static String statusJson(){String j="{\"temp\":"+(isnan(tempC)?String("null"):String(tempC,1))+",\"target\":"+String(targetC)+",\"duration\":"+String(durationS)+",\"uiAuth\":"+String(uiAuth?"true":"false")+",\"encoderMode\":"+String(encoderTimeMode?"\"time\"":"\"temperature\"")+",\"nanoAckSeq\":"+String(lastAckSeq)+",\"nanoAckOk\":"+String(lastAckOk?"true":"false")+",\"heater\":"+String(heaterOn?"true":"false")+",\"lidClosed\":"+String(lidClosed?"true":"false")+",\"nanoOnline\":"+String(nanoUp?"true":"false")+",\"fault\":"+String(sensorFault?"true":"false")+",\"run\":"+String(runEnabled?"true":"false")+",\"count\":"+String(completed)+",\"remaining\":"+String(bakeState==1&&bakeElapsedS<durationS?durationS-bakeElapsedS:0)+",\"overtime\":"+String(overtimeS)+",\"bakeAvg\":"+(isnan(avgBake())?String("null"):String(avgBake(),1))+",\"openAvg\":"+(isnan(avgOpen())?String("null"):String(avgOpen(),1))+",\"rate\":"+(isnan(ratePerHour())?String("null"):String(ratePerHour(),1))+"}";return j;}
static void sendStatus(){if(!authorized())return;server.send(200,"application/json",statusJson());}
static void sendHistory(){if(!authorized())return;uint32_t from=server.hasArg("from")?(uint32_t)server.arg("from").toInt():0;String j="{\"samples\":[";bool first=true;uint16_t start=(histHead+1080-histCount)%1080;for(uint16_t i=0;i<histCount;i++){Sample &s=history[(start+i)%1080];if(from&&s.sec<=from)continue;if(!first)j+=',';first=false;j+="["+String(s.sec)+","+(s.temp10==-32768?String("null"):String(s.temp10/10.0f,1))+","+String(s.set10/10.0f,1)+","+String(s.heater)+","+String(s.lid)+"]";}j+="]}";server.send(200,"application/json",j);}
static void sendEvents(){if(!authorized())return;String j="{\"events\":[";bool f=true;uint16_t start=(eventHead+100-eventCount)%100;for(uint16_t i=0;i<eventCount;i++){OpenEvent &e=openings[(start+i)%100];if(!f)j+=',';f=false;j+="["+String(e.sec)+","+String(e.openSec)+"]";}j+="],\"heater\":[";f=true;start=(heaterHead+200-heaterCount)%200;for(uint16_t i=0;i<heaterCount;i++){HeaterEvent &e=heaterEvents[(start+i)%200];if(!f)j+=',';f=false;j+="["+String(e.sec)+","+String(e.on)+","+String(e.baseline)+"]";}j+="]}";server.send(200,"application/json",j);}

