static String jsonEscape(const String &value){String out;out.reserve(value.length()+8);for(size_t i=0;i<value.length();i++){char c=value[i];if(c=='"'||c=='\\'){out+='\\';out+=c;}else if(c=='\n')out+="\\n";else if(c=='\r')out+="\\r";else if((uint8_t)c>=0x20)out+=c;}return out;}
static bool wifiScanRunning=false;
static void handleWifiScan(){
  if(!apMode){server.send(403,"application/json","{\"state\":\"unavailable\",\"networks\":[]}");return;}
  if(server.hasArg("start")&&!wifiScanRunning){
    Serial.println(F("[ESP] Scanning nearby Wi-Fi networks"));
    int result=WiFi.scanNetworks(true);
    wifiScanRunning=(result==WIFI_SCAN_RUNNING);
    if(result>=0)wifiScanRunning=false;
  }
  int count=WiFi.scanComplete();
  if(count==WIFI_SCAN_RUNNING){server.send(200,"application/json","{\"state\":\"scanning\",\"networks\":[]}");return;}
  if(count<0){
    Serial.printf("[ESP] Wi-Fi scan failed (%d)\n",count);
    wifiScanRunning=false;WiFi.scanDelete();server.send(200,"application/json","{\"state\":\"failed\",\"networks\":[]}");return;
  }
  String json="{\"state\":\"done\",\"networks\":[";bool first=true;
  for(int i=0;i<count;i++){
    String ssid=WiFi.SSID(i);if(!ssid.length())continue;if(!first)json+=',';first=false;
    json+="{\"ssid\":\""+jsonEscape(ssid)+"\",\"rssi\":"+String(WiFi.RSSI(i))+",\"secure\":"+String(WiFi.encryptionType(i)!=WIFI_AUTH_OPEN?"true":"false")+"}";
  }
  json+="]}";Serial.printf("[ESP] Wi-Fi scan complete: %d networks\n",count);
  WiFi.scanDelete();wifiScanRunning=false;server.send(200,"application/json",json);
}
static void handleSet(){if(!authorized())return;int t=server.arg("target").toInt(),d=server.arg("duration").toInt();if(t<100||t>160||d<10||d>90){server.send(400,"text/plain","Temperature 100-160 C, time 10-90 s");return;}targetC=t;durationS=d;prefs.putInt("target",t);prefs.putInt("duration",d);settingsDirty=false;Serial.printf("[ESP] Settings saved: target=%d C, duration=%d s\n",targetC,durationS);if(nanoUp)lastControlMs=0;server.send(200,"application/json","{\"ok\":true}");}
static void handleControl(){if(!authorized())return;String c=server.arg("cmd");if(c=="STOP"){runEnabled=false;bakeState=0;Serial.println(F("[ESP] Web STOP accepted"));if(nanoUp)lastControlMs=0;server.send(200,"application/json","{\"ok\":true}");}else if(c=="RUN"){if(!nanoUp||sensorFault||!lidClosed){Serial.println(F("[ESP] Web START rejected by safety checks"));server.send(409,"application/json","{\"ok\":false,\"error\":\"Nano offline, sensor fault, or lid open\"}");return;}runEnabled=true;Serial.println(F("[ESP] Web START accepted"));if(nanoUp)lastControlMs=0;server.send(200,"application/json","{\"ok\":true}");}else server.send(400,"text/plain","Unknown command");}
static void handleAuth(){if(!authorized())return;String p=server.arg("password");bool en=server.arg("enabled")=="1";if((en&&!updatePasswordSet&&!p.length())||(p.length()&&p.length()<8)){server.send(400,"text/plain","Set a password of at least 8 characters for UI/OTA");return;}if(p.length()){uiPassword=p;prefs.putString("uiPass",p);updatePasswordSet=true;ArduinoOTA.setPassword(uiPassword.c_str());if(!apMode&&!arduinoOtaStarted){ArduinoOTA.setHostname("oblatkovac");ArduinoOTA.begin();arduinoOtaStarted=true;}}uiAuth=en;prefs.putBool("uiAuth",en);server.send(200,"application/json","{\"ok\":true}");}
